:root {
  --navy-950: #0a1628;
  --navy-900: #10213a;
  --navy-800: #1b3356;
  --teal-500: #0f9d9a;
  --gold-500: #c9a24f;
  --gray-50: #f7f9fc;
  --gray-100: #edf1f6;
  --gray-200: #d8e0ea;
  --gray-300: #bcc9d8;
  --gray-500: #63748a;
  --gray-700: #344155;
  --white: #ffffff;
  --ink: #101828;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --shadow-sm: 0 4px 20px rgba(10, 22, 40, 0.08);
  --shadow-md: 0 20px 60px rgba(10, 22, 40, 0.18);
  --container: 1180px;
  --transition: 220ms ease;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: "Inter", "Segoe UI", Roboto, Arial, sans-serif;
  color: var(--ink);
  line-height: 1.6;
  background: var(--white);
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

h1,
h2,
h3,
h4 {
  margin: 0;
  line-height: 1.2;
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  color: var(--navy-950);
}

p {
  margin: 0;
}

.container {
  width: min(var(--container), 92vw);
  margin: 0 auto;
}

.section {
  padding: 88px 0;
}

.kicker {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 12px;
  font-weight: 700;
  color: var(--teal-500);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 46px;
  padding: 0 20px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 600;
  font-size: 15px;
  transition: transform var(--transition), box-shadow var(--transition), background var(--transition);
}

.btn:focus-visible,
.nav-link:focus-visible,
.mega-link:focus-visible,
.tab-button:focus-visible,
.mobile-toggle:focus-visible,
.mobile-accordion-toggle:focus-visible,
.carousel-btn:focus-visible {
  outline: 2px solid var(--teal-500);
  outline-offset: 2px;
}

.btn-primary {
  background: linear-gradient(135deg, var(--gold-500), #b78a35);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 24px rgba(20, 28, 47, 0.22);
}

.btn-secondary {
  border-color: rgba(255, 255, 255, 0.55);
  color: var(--white);
}

.top-banner {
  background: var(--navy-950);
  color: var(--white);
  padding: 12px 0;
  font-size: 14px;
}

.top-banner .container {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
}

.top-banner a {
  color: #d9e7ff;
  text-decoration: underline;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 255, 255, 0.98);
  border-bottom: 1px solid var(--gray-100);
  backdrop-filter: blur(8px);
}

.nav-shell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 84px;
  gap: 24px;
}

.logo {
  font-family: "Playfair Display", Georgia, serif;
  font-size: 30px;
  letter-spacing: 0.02em;
  color: var(--navy-950);
}

.logo span {
  color: var(--gold-500);
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 24px;
}

.nav-link {
  font-size: 15px;
  font-weight: 500;
  color: var(--gray-700);
  padding: 12px 2px;
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--navy-950);
}

.nav-link.active::after,
.nav-link:hover::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 4px;
  height: 2px;
  background: var(--teal-500);
}

.services-menu {
  position: relative;
}

.mega-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  width: min(960px, 90vw);
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 0;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity var(--transition), transform var(--transition);
}

.services-menu.open .mega-menu,
.services-menu:hover .mega-menu,
.services-menu:focus-within .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.mega-column {
  padding: 26px;
}

.mega-column + .mega-column {
  border-left: 1px solid var(--gray-100);
  background: var(--gray-50);
  border-radius: 0 var(--radius-lg) var(--radius-lg) 0;
}

.mega-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-500);
  margin-bottom: 14px;
}

.mega-links {
  display: grid;
  gap: 10px;
}

.mega-link {
  display: block;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  color: var(--gray-700);
}

.mega-link:hover {
  background: rgba(15, 157, 154, 0.1);
  color: var(--navy-900);
}

.mobile-toggle {
  display: none;
  width: 44px;
  height: 44px;
  border: 1px solid var(--gray-200);
  border-radius: 10px;
  background: var(--white);
}

.mobile-nav {
  display: none;
  border-top: 1px solid var(--gray-100);
  padding: 10px 0 16px;
}

.mobile-nav.open {
  display: block;
}

.mobile-link,
.mobile-accordion-toggle {
  width: 100%;
  min-height: 46px;
  padding: 12px 0;
  border: 0;
  background: none;
  text-align: left;
  font-size: 16px;
  color: var(--navy-900);
  border-bottom: 1px solid var(--gray-100);
}

.mobile-accordion-panel {
  display: none;
  padding: 8px 0 12px 14px;
}

.mobile-accordion-item.open .mobile-accordion-panel {
  display: grid;
  gap: 4px;
}

.mobile-sublink {
  font-size: 14px;
  color: var(--gray-700);
  min-height: 40px;
  display: flex;
  align-items: center;
}

.hero {
  position: relative;
  min-height: 68vh;
  color: var(--white);
  display: flex;
  align-items: end;
}

.hero img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, rgba(10, 22, 40, 0.88), rgba(10, 22, 40, 0.44));
}

.hero-content {
  position: relative;
  z-index: 1;
  padding: 96px 0 78px;
  width: min(760px, 94vw);
}

.hero h1 {
  color: var(--white);
  font-size: clamp(34px, 5.4vw, 62px);
  margin: 16px 0 18px;
}

.hero p {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.9);
  max-width: 640px;
}

.hero-actions {
  margin-top: 30px;
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}

.card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.card h3 {
  font-size: 24px;
  margin-bottom: 12px;
}

.card p {
  color: var(--gray-700);
}

.card .link {
  margin-top: 18px;
  display: inline-block;
  font-size: 14px;
  font-weight: 600;
  color: var(--teal-500);
}

.about-panel {
  background: var(--gray-50);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 42px;
}

.about-panel h2,
.section-title {
  font-size: clamp(29px, 3.4vw, 44px);
  margin-bottom: 14px;
}

.what-we-do {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 28px;
  align-items: stretch;
}

.tabs-list {
  display: grid;
  gap: 10px;
}

.tab-button {
  width: 100%;
  padding: 18px;
  border-radius: 12px;
  border: 1px solid var(--gray-200);
  background: var(--white);
  text-align: left;
  font-weight: 600;
  color: var(--navy-900);
  min-height: 52px;
}

.tab-button.active {
  border-color: var(--teal-500);
  background: rgba(15, 157, 154, 0.08);
}

.tab-panel {
  display: none;
  background: var(--navy-950);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px;
  min-height: 280px;
}

.tab-panel.active {
  display: block;
}

.tab-panel h3 {
  color: var(--white);
  margin-bottom: 12px;
  font-size: 33px;
}

.tab-panel p {
  color: rgba(255, 255, 255, 0.9);
  margin-bottom: 18px;
}

.insight-card img {
  height: 160px;
  object-fit: cover;
  border-radius: 10px;
  margin-bottom: 14px;
}

.tag {
  display: inline-flex;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(15, 157, 154, 0.12);
  color: var(--teal-500);
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 8px;
}

.newsletter {
  background: linear-gradient(120deg, var(--navy-950), var(--navy-800));
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.footer {
  background: var(--navy-950);
  color: rgba(255, 255, 255, 0.86);
  padding: 56px 0 28px;
  margin-top: 90px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.2fr repeat(3, 1fr);
  gap: 24px;
}

.footer h4 {
  color: var(--white);
  font-size: 18px;
  margin-bottom: 12px;
}

.footer a {
  display: block;
  margin-bottom: 8px;
  color: rgba(255, 255, 255, 0.86);
  font-size: 14px;
}

.page-hero {
  position: relative;
  min-height: 48vh;
  display: flex;
  align-items: end;
  color: var(--white);
}

.page-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, rgba(10, 22, 40, 0.88), rgba(10, 22, 40, 0.46));
}

.page-hero-content {
  position: relative;
  z-index: 1;
  padding: 80px 0 60px;
}

.page-hero h1 {
  color: var(--white);
  font-size: clamp(32px, 4.4vw, 56px);
  margin: 12px 0;
}

.capability-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.capability-card {
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  padding: 22px;
  background: var(--white);
}

.capability-card h3 {
  font-size: 22px;
  margin-bottom: 10px;
}

.two-col {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 28px;
}

.topic-list {
  display: grid;
  gap: 10px;
}

.topic-item {
  padding: 14px;
  border-radius: 10px;
  border: 1px solid var(--gray-100);
  background: var(--gray-50);
  font-weight: 600;
  color: var(--navy-900);
}

.carousel {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  background: var(--white);
}

.carousel-track {
  display: flex;
  transition: transform var(--transition);
}

.carousel-slide {
  min-width: 100%;
  padding: 30px;
}

.carousel-controls {
  display: flex;
  gap: 10px;
  margin-top: 14px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  border: 1px solid var(--gray-200);
  background: var(--white);
}

@media (max-width: 1080px) {
  .desktop-nav,
  .header-cta {
    display: none;
  }

  .mobile-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .what-we-do,
  .two-col,
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .capability-grid,
  .grid-3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .section {
    padding: 70px 0;
  }

  .top-banner .container {
    flex-direction: column;
    align-items: flex-start;
  }

  .hero {
    min-height: 62vh;
  }

  .hero p {
    font-size: 16px;
  }

  .about-panel,
  .newsletter,
  .tab-panel {
    padding: 28px;
  }

  .capability-grid,
  .grid-3 {
    grid-template-columns: 1fr;
  }
}
